import java.io.*;
import java.util.*;

public final class Solution {

  static BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
  static BufferedWriter bw = new BufferedWriter(new OutputStreamWriter(System.out));
  static StringTokenizer st;

  public static void main(String[] args) throws IOException {
    String s = br.readLine();
    int n = s.length();

    // Check if the number can be divisible by 25
    // A number is divisible by 25 if its last two digits are 00, 25, 50, or 75

    long total = 0;

    // Try all possible last two digits combinations that make the number divisible by 25
    String[] validEndings = {"00", "25", "50", "75"};

    for (String ending : validEndings) {
      char last1 = ending.charAt(0);
      char last2 = ending.charAt(1);

      // Check if the last two characters of s can match this ending
      boolean possible = true;
      int xDigit = -1; // If X is used, what digit it represents

      // Check last character
      char sLast2 = s.charAt(n - 2);
      char sLast1 = s.charAt(n - 1);

      // Process last two positions
      if (sLast2 == '_') {
        // Can be any digit
      } else if (sLast2 == 'X') {
        if (xDigit == -1) {
          xDigit = last1 - '0';
        } else if (xDigit != (last1 - '0')) {
          possible = false;
        }
      } else if (sLast2 != last1) {
        possible = false;
      }

      if (sLast1 == '_') {
        // Can be any digit
      } else if (sLast1 == 'X') {
        if (xDigit == -1) {
          xDigit = last2 - '0';
        } else if (xDigit != (last2 - '0')) {
          possible = false;
        }
      } else if (sLast1 != last2) {
        possible = false;
      }

      if (!possible) {
        continue;
      }

      // Now count the number of ways to fill the remaining positions
      long ways = 1;
      boolean hasX = false;

      for (int i = 0; i < n - 2; i++) {
        char c = s.charAt(i);
        if (c == '_') {
          if (i == 0) {
            // First digit cannot be 0
            ways *= 9;
          } else {
            ways *= 10;
          }
        } else if (c == 'X') {
          hasX = true;
        }
      }

      // If there are X's in the prefix, we need to check consistency
      if (hasX) {
        // If we already determined xDigit from the last two positions
        if (xDigit != -1) {
          // All X's must be this digit
          // Check if any X in prefix conflicts with this
          boolean valid = true;
          for (int i = 0; i < n - 2; i++) {
            if (s.charAt(i) == 'X') {
              // X must be xDigit
              // No additional constraint needed since we already set xDigit
            }
          }
          // X's are consistent with the ending
        } else {
          // X's in prefix can be any digit (0-9), but if first digit is X, it can't be 0
          boolean firstIsX = (n > 2 && s.charAt(0) == 'X');
          if (firstIsX) {
            ways *= 9; // X can be 1-9
          } else {
            ways *= 10; // X can be 0-9
          }
        }
      }

      total += ways;
    }

    bw.write(total + "\n");
    bw.flush();
  }
}
